/** Returns localized stage label for the top progress header. */
export function localizeStageLabel(stage: string, lang?: string | null): string {
  if (!lang || lang === "en") {
    const enMap: Record<string, string> = {
      complaint: "Chief Complaint",
      socrates: "History of Present Illness",
      "hpi-open": "Tell me more",
      past: "Past Medical History",
      surgical: "Past Surgical History",
      medications: "Current Medications",
      allergies: "Allergies",
      family: "Family History",
      personal: "Personal History",
      female: "Menstrual & Obstetric History",
      ros: "Review of Systems",
      ayush: "AYUSH Assessment",
      complete: "Complete",
    };
    return enMap[stage] ?? stage;
  }
  return MULTI_STAGE_LABELS[lang]?.[stage] ?? MULTI_STAGE_LABELS.hi?.[stage] ?? stage;
}

/** Returns localized surgery item label. */
export function localizeSurgery(surgery: string, lang?: string | null): string {
  if (!lang || lang === "en") return surgery;
  return MULTI_SURGERIES[lang]?.[surgery] ?? MULTI_SURGERIES.hi?.[surgery] ?? surgery;
}

/** Returns localized common medication label. */
export function localizeCommonMed(med: string, lang?: string | null): string {
  if (!lang || lang === "en") return med;
  return MULTI_COMMON_MEDS[lang]?.[med] ?? MULTI_COMMON_MEDS.hi?.[med] ?? med;
}

