      doctorBtn: "Not sure or no specific complaint — let the doctor decide",
      socratesHeader: "SOCRATES · History of Present Illness",
      hpiTitle: "Now tell us more in your own words",
      hpiSubtitle: "How exactly did it start and how has it been since?",
      hpiPlaceholder: "Please describe your symptoms by speaking or typing...",
      clarifyBadge: "Let a clinical assistant ask clarifying questions",
      askBtn: "Ask",
      askAgainBtn: "Ask again",
      pastTitle: "Past medical history",
      pastSubtitle: "Do you have any of these conditions? (tap all that apply)",
      surgicalTitle: "Past Surgical History",
      surgicalSubtitle: "Any previous surgery or operation? (tap all that apply)",
      medsTitle: "Current Medications",
      medsSubtitle: "Which medicines are you currently taking?",
      allergiesTitle: "Drug / Allergy History",
      allergiesSubtitle: "Do you have any allergies? (tap all that apply)",
      familyTitle: "Family History",
      familySubtitle: "Does any family member have diabetes, BP, heart disease, TB, or cancer?",
      familyPlaceholder: "e.g. Father has diabetes, mother has high BP...",
      personalTitle: "Personal History",
      smokingTitle: "Smoking / Tobacco",
      alcoholTitle: "Alcohol",
      femaleTitle: "Women's health · menstrual & obstetric history",
      femaleSubtitle: "Please share menstrual and pregnancy history.",
      periodsQuestion: "Are your periods regular?",
      pregnantQuestion: "Have you ever been pregnant?",
      lmpLabel: "Last period / cycle details (optional)",
      lmpPlaceholder: "e.g. 2 weeks ago, heavy bleeding, severe pain",
      obstLabel: "Gravida / Para & any complications (optional)",
      obstPlaceholder: "e.g. 2 pregnancies, normal delivery",
      rosTitle: "Review of Systems",
      ayushTitle: "AYUSH Assessment · Dashavidha Pariksha",
      ayushDoneTitle: "AYUSH Assessment Complete",
      ayushDoneSubtitle: "Dashavidha Pariksha and Ahara-Vihara assessment captured.",
      almostDoneTitle: "Almost done",
      almostDoneSubtitle: "Thank you for answering. We have your complete history now.",
      scanContinueBtn: "Continue to document scan",
      nextBtn: "Next",
      voiceHint: "Tap screen or speak with microphone",
