/** Returns localized question text for any supported language, or fallback. */
export function localizeQuestion(id: string, lang?: string | null): string | undefined {
  if (!lang || lang === "en") return undefined;
  return MULTI_QUESTIONS[lang]?.[id] ?? MULTI_QUESTIONS.hi?.[id];
}

/** Returns localized options list for any supported language, or fallback. */
export function localizeOptions(id: string, lang?: string | null, fallback: string[] = []): string[] {
  if (!lang || lang === "en") return fallback;
  return MULTI_OPTIONS[lang]?.[id] ?? MULTI_OPTIONS.hi?.[id] ?? fallback;
}

